@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Location {
  + name : string
  + address : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
  + isAccomplished : boolean
}

Organizer "1..*" -- "1..*" Event : organizes
Event "1" -- "1" EventType : is a type of
Event "1" -- "1" Location : at
Event "1" -- "0..*" Task : has checklist
Event "1" -- "0..*" Attendee : invites
Attendee "0..1" -- "0..1" Organizer : attends

Organizer "1" -- "0..*" Task : creates
Task "0..*" -- "0..1" Attendee : is assigned to

@enduml

